/**
 * Get the IANA timezone for an airport code.
 * Returns null if the airport is not in the database.
 */
export function getAirportTimezone(iataCode) {
  if (!iataCode) return null;
  const c = String(iataCode).toUpperCase();
  // Tier 1: hand-curated AIRPORT_TIMEZONES (authoritative).
  if (AIRPORT_TIMEZONES[c]) return AIRPORT_TIMEZONES[c];
  // K-prefix tolerance for US ICAO vs FAA mismatch: KAPF → APF.
  if (c.length === 4 && c.startsWith('K') && AIRPORT_TIMEZONES[c.slice(1)]) return AIRPORT_TIMEZONES[c.slice(1)];
  // Tier 2: bulk EXTERNAL_TIMEZONES from OurAirports.
  if (EXTERNAL_TIMEZONES[c]) return EXTERNAL_TIMEZONES[c];
  if (c.length === 4 && c.startsWith('K') && EXTERNAL_TIMEZONES[c.slice(1)]) return EXTERNAL_TIMEZONES[c.slice(1)];
  if (c.length === 3 && EXTERNAL_TIMEZONES['K' + c]) return EXTERNAL_TIMEZONES['K' + c];
  return null;
}

/**
 * Format a Date as time in the airport's local timezone.
 * Returns { time: "9:30 AM", tz: "EDT" } or { time: "1430Z", tz: "UTC" } as fallback.
 */
export function formatLocalTime(date, iataCode) {
  if (!date || !(date instanceof Date) || isNaN(date.getTime())) {
    return { time: '—', tz: '' };
  }
  const tz = getAirportTimezone(iataCode);
  // When the airport isn't in our database, fall back to the device's local
  // timezone instead of Zulu. For US-based ops users this is far more useful
  // than an opaque "1500Z UTC" — they see what time the trip is "for them".
  // The TZ abbreviation makes it clear (e.g. "10:00 AM EDT") so there's no
  // confusion about which clock is being shown.
  if (!tz) {
    try {
      const time = new Intl.DateTimeFormat('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      }).format(date);
      const tzAbbr = new Intl.DateTimeFormat('en-US', {
        timeZoneName: 'short',
      }).formatToParts(date).find(p => p.type === 'timeZoneName')?.value || '';
      return { time, tz: tzAbbr };
    } catch (err) {
      const hh = String(date.getUTCHours()).padStart(2, '0');
      const mm = String(date.getUTCMinutes()).padStart(2, '0');
      return { time: `${hh}${mm}Z`, tz: 'UTC' };
    }
  }
  try {
    const time = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    }).format(date);
    // Get TZ abbreviation (EDT, PST, etc)
    const tzAbbr = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      timeZoneName: 'short',
    }).formatToParts(date).find(p => p.type === 'timeZoneName')?.value || '';
    return { time, tz: tzAbbr };
  } catch (err) {
    const hh = String(date.getUTCHours()).padStart(2, '0');
    const mm = String(date.getUTCMinutes()).padStart(2, '0');
    return { time: `${hh}${mm}Z`, tz: 'UTC' };
  }
}

/**
 * Format a Date as date in airport's local time.
 * Returns "27 APR 2026" in the airport's TZ.
 */
export function formatLocalDate(date, iataCode) {
  if (!date || !(date instanceof Date) || isNaN(date.getTime())) return '';
  const tz = getAirportTimezone(iataCode) || 'UTC';
  try {
    const parts = new Intl.DateTimeFormat('en-US', {
      timeZone: tz,
      day: '2-digit',
      month: 'short',
      year: 'numeric',
    }).formatToParts(date);
    const d = parts.find(p => p.type === 'day')?.value || '';
    const m = (parts.find(p => p.type === 'month')?.value || '').toUpperCase();
    const y = parts.find(p => p.type === 'year')?.value || '';
    return `${d} ${m} ${y}`;
  } catch (err) {
    return '';
  }
}
